_sage_const_1 = Integer(1); _sage_const_40 = Integer(40); _sage_const_10 = Integer(10); _sage_const_16 = Integer(16); _sage_const_4 = Integer(4); _sage_const_9 = Integer(9); _sage_const_160 = Integer(160); _sage_const_3 = Integer(3); _sage_const_1000 = Integer(1000); _sage_const_11 = Integer(11); _sage_const_31 = Integer(31); _sage_const_19 = Integer(19); _sage_const_23 = Integer(23); _sage_const_2 = Integer(2); _sage_const_5 = Integer(5); _sage_const_0 = Integer(0); _sage_const_13 = Integer(13); _sage_const_2000000 = Integer(2000000); _sage_const_32 = Integer(32)
import sys
import time
from multiprocessing import Process, Event

def precompute_V():
    V = {_sage_const_1 }
    for s in range(_sage_const_40 ):
        fs = (_sage_const_10  * _sage_const_16 **s + _sage_const_16  * _sage_const_4 **s + _sage_const_10 ) // _sage_const_9 
        for i in range(_sage_const_160 ):
            val = fs * _sage_const_4 **i
            V.add(val)
    return sorted(list(V))

all_V = precompute_V()
small_primes = [p for p in prime_range(_sage_const_3 , _sage_const_1000 ) if p % _sage_const_4  == _sage_const_3 ]

# 5 base primes
selected_primes = [_sage_const_3 , _sage_const_11 , _sage_const_31 , _sage_const_19 , _sage_const_23 ]

# Residues optimized for N up to 10^10 (from our debug script)
selected_residues = {_sage_const_3 : _sage_const_1 , _sage_const_11 : _sage_const_2 , _sage_const_31 : _sage_const_4 , _sage_const_19 : _sage_const_5 , _sage_const_23 : _sage_const_2 }

moduli = [_sage_const_2 ] + selected_primes
residues = [_sage_const_1 ] + [selected_residues[p] for p in selected_primes]
from math import prod as math_prod
base_prod = math_prod(moduli)
N0 = int(crt(residues, moduli))

print(f"CRT base: N0 = {N0}")
